/* ทะเบียนตัวอย่างสำหรับทดสอบ `check-ทะเบียนปลายเปิด.mjs` — **ข้อมูลล้วน ไม่มีผลข้างเคียง**
   (รูปเดียวกับที่ขอให้ฝั่งท่อแยกไฟล์ออกมา) · โหมดเลือกด้วย env `REGISTRY_MODE` */
const โหมด = process.env.REGISTRY_MODE || 'ตรง'
export const ปลายเปิด = {
  /* ช่องที่จอ `/core/sales` อ่านจริง (statusesAll มีอยู่ในไฟล์นั้นแน่) */
  'orders.statusesAll': { ปลายเปิด: true, ใครอ่าน: 'gucut-next · /core/sales', อ่านเป็น: 'สร้างรายชื่อแท็บ' },
  /* ทิศ ①: จดว่ามีคนอ่าน แต่ชื่อช่องไม่มีในจอเลย */
  ...(โหมด === 'ทิศ1'
    ? { 'orders.ช่องที่จอเลิกอ่านแล้ว': { ปลายเปิด: true, ใครอ่าน: 'gucut-next · /core/sales', อ่านเป็น: 'เรนเดอร์เป็นแถว' } }
    : {}),
  /* ทิศ ②: จดว่าไม่มีใครอ่าน แต่จออ่านอยู่จริง */
  ...(โหมด === 'ทิศ2'
    ? { 'orders.statusesAllError': { ปลายเปิด: false, ใครอ่าน: 'ไม่มี (วัด 14 ต.ค. 2569)', อ่านเป็น: '—' } }
    : {}),
  /* ค่าเก่าแบบสตริง — ตรวจไม่ได้ และต้องถูกนับให้เห็น */
  'transfers.byKind': 'ชนิดใบโอน — ZORT เพิ่มชนิดได้',
}
